const fs = require('fs')
const path = require('path')
const b4a = require('b4a')
const Corestore = require('corestore')
const gnome_dconf = require('gnome-dconf')
const shell_extensions = require('shell-extensions')
const local_settings = require('local-settings')
const sync_rules = require('sync-rules')
const safety_backup = require('safety-backup')
const settings_store = require('settings-store')
const settings_sync = require('settings-sync')
const device_network = require('device-network')
const device_pairing = require('device-pairing')

module.exports = sync_device

// everything one device needs, kept in one folder: store/, config.json, rules.json, synced.json, backups/
function sync_device ({ dir, bootstrap = null, log = console.log }) {
  const state = { store: null, settings: null, sync: null, network: null, pairing: null, watchers: [], timer: null, busy: false, declined: null, failed: new Set(), confirm: null }
  const dconf = gnome_dconf()
  const rules = sync_rules({ file: path.join(dir, 'rules.json') })
  const local = local_settings({ dconf, extensions: shell_extensions({ dconf }), rules })
  const backup = safety_backup({ dir: path.join(dir, 'backups'), local })
  const api = { dconf, rules, backup, init, open, invite, join, run, close, get settings () { return state.settings }, get sync () { return state.sync } }
  return api

  // first device: makes new settings
  async function init (name) {
    if (await read_config(dir)) throw new Error('already set up in ' + dir)
    await open_store()
    await open_settings({ key: null, name })
  }

  // a device that is already set up
  async function open () {
    const config = await read_config(dir)
    if (!config) throw new Error('not set up yet, run `gnome-hypersync init` or `gnome-hypersync join <code>`')
    await open_store()
    await open_settings({ key: b4a.from(config.key, 'hex'), name: config.name })
  }

  // prints the code, asks for the digits shown on the new device, then keeps syncing
  async function invite ({ on_code, on_request, confirm }) {
    await open()
    await start_network()
    const { code, paired } = state.pairing.invite({ settings: state.settings, on_request })
    on_code(code)
    const device = await paired
    log(`paired with ${device.name}`)
    await run({ confirm })
  }

  // new device: pairs with the code, opens the settings it got, then keeps syncing
  async function join ({ code, name, on_digits, confirm }) {
    if (await read_config(dir)) throw new Error('already set up in ' + dir)
    await open_store()
    await start_network()
    const writer_key = await settings_store.get_writer_key(state.store)
    const keys = await state.pairing.join({ code, writer_key, name, on_digits })
    await open_settings({ key: keys.key, encryption_key: keys.encryption_key, name })
    log('paired, waiting to be added as a writer')
    await run({ confirm })
  }

  // watches dconf and the settings, sends changes from here, asks confirm(changes) before applying others
  async function run ({ confirm }) {
    if (!state.network) await start_network()
    state.network.join(state.settings.discovery_key)
    state.watchers = [...rules.allowed_dirs, '/org/gnome/shell/enabled-extensions'].map(watched => dconf.watch(watched, schedule_sync))
    state.settings.on('update', schedule_sync)
    state.confirm = confirm
    schedule_sync()
    log('syncing, press ctrl+c to stop')
  }

  async function close () {
    clearTimeout(state.timer)
    for (const watcher of state.watchers) watcher.stop()
    if (state.pairing) await state.pairing.close()
    if (state.network) await state.network.stop()
    if (state.settings) await state.settings.close()
    if (state.store) await state.store.close()
  }

  /***************************************
  PROCEDURES
  ***************************************/
  async function open_store () {
    await fs.promises.mkdir(dir, { recursive: true })
    state.store = new Corestore(path.join(dir, 'store'))
    await state.store.ready().catch(on_store_error)
    await rules.load()
  }

  async function open_settings ({ key, encryption_key = null, name }) {
    state.settings = settings_store({ store: state.store, key, encryption_key })
    await state.settings.ready()
    if (!key) await state.settings.add_device(state.settings.writer_key, name)
    await write_config(dir, { key: b4a.toString(state.settings.key, 'hex'), name })
    state.sync = settings_sync({ local, store: state.settings, rules, backup, file: path.join(dir, 'synced.json') })
    await state.sync.load()
  }

  async function start_network () {
    state.network = device_network({ store: state.store, bootstrap })
    state.pairing = device_pairing({ swarm: await state.network.start() })
  }

  function schedule_sync () {
    clearTimeout(state.timer)
    state.timer = setTimeout(sync_now, 300)
  }

  // one at a time: send what changed here, then offer what changed elsewhere
  async function sync_now () {
    if (state.busy) return schedule_sync()
    state.busy = true
    try {
      if (state.settings.writable) await send_local_changes()
      await offer_remote_changes()
    } catch (err) {
      log('sync failed: ' + err.message)
    }
    state.busy = false
  }

  async function send_local_changes () {
    const sent = await state.sync.push_local_changes()
    if (sent.length) log(`sent ${sent.length} change(s): ${sent.join(', ')}`)
  }

  async function offer_remote_changes () {
    const changes = (await state.sync.diff()).filter(change => !state.failed.has(change.key + '=' + change.remote)) // failed ones are retried after a restart
    const seen = JSON.stringify(changes)
    if (!changes.length || seen === state.declined) return // dont ask twice for the same changes
    if (!(await state.confirm(changes))) {
      state.declined = seen
      return
    }
    const { id, failed } = await state.sync.apply(changes)
    log(`applied ${changes.length - failed.length} change(s), undo with: gnome-hypersync rollback ${id}`)
    for (const change of failed) log(`not applied: ${change.key}: ${change.error}`)
    for (const change of failed) state.failed.add(change.key + '=' + change.remote)
  }
}

/***************************************
HELPERS
***************************************/
function on_store_error (err) {
  if (/lock/i.test(err.message)) throw new Error('gnome-hypersync is already running on this device, stop `gnome-hypersync run` first')
  throw err
}

function read_config (dir) { return fs.promises.readFile(path.join(dir, 'config.json'), 'utf8').then(JSON.parse).catch(() => null) }
function write_config (dir, config) { return fs.promises.writeFile(path.join(dir, 'config.json'), JSON.stringify(config, null, 2)) }
